@startuml

class Customer {
  + Name : string
  + Surname : string
  + Email : string
  + Telephone : string
  + HomeAddress : string
}

class Order {
  + TotalCost : double
  + EstimatedDeliveryTime : datetime
  + Status : string
}

class Dish {
  + Name : string
}

class Payment {
  + PaymentMethod : string
  + IsSuccessful : boolean
}

class Kitchen {
  + CurrentWorkload : int
}

class DeliveryStaff {
  + ReportCompletion()
}

Customer "1" -- "*" Order : places
Order "*" -- "1..*" Dish : contains
Order "1" -- "1" Payment : processed_by
Order "*" -- "1" Kitchen : sent_to
Order "1" -- "1" DeliveryStaff : delivered_by

@enduml

